using System;using System.Net;using System.Net.Http;using System.Threading;using System.Threading.Tasks;using GentlyPick.Updates;
class Fake:HttpMessageHandler {public int api,feed;public string json;protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage r,CancellationToken t){bool first=r.RequestUri.Host=="api.github.com";if(first)api++;else feed++;return Task.FromResult(new HttpResponseMessage(first?HttpStatusCode.Forbidden:HttpStatusCode.OK){Content=new StringContent(first?"rate limit exceeded":json)});}}
class Test {static void Main(){Run().GetAwaiter().GetResult();}static async Task Run(){var h=new Fake{json=System.IO.File.ReadAllText("update-feed.json")};using(var c=new HttpClient(h)){var a=await ReleaseClient.LatestWith(c,new Version(1,0,5));if(a.Version!=new Version(1,0,6)||a.Size<1||a.Sha256.Length!=64)throw new Exception("fallback invalid");var b=await ReleaseClient.LatestWith(c,new Version(1,0,6));if(b.Version!=a.Version||h.api!=1||h.feed!=1)throw new Exception("cache failed");}Console.WriteLine("PASS: API 403 -> fallback; digest/size/version validated; repeated check uses cache");}}
